+// BindFor allows binding of implementations to the compile-time type. It
+// is equivalent to BindTo(v, (*T)(nil)), but can usually infer the
+// correct type T.
+func BindFor[T any](v T) Option {
+	return BindTo(v, (*T)(nil))
+}
